;(()=>{try{
    const LIGHTBOX_ID="rl-pm-image-lightbox";
    let escHandlerBound=false;
    const onKeyDown=(ev)=>{
        if(ev.key!=="Escape") return;
        const existing=document.getElementById(LIGHTBOX_ID);
        if(!existing) return;
        ev.preventDefault();
        ev.stopPropagation();
        if(typeof ev.stopImmediatePropagation==="function") ev.stopImmediatePropagation();
        removeLightbox();
    };
    const bindEsc=()=>{
        if(escHandlerBound) return;
        document.addEventListener("keydown", onKeyDown, true);
        escHandlerBound=true;
    };
    const unbindEsc=()=>{
        if(!escHandlerBound) return;
        document.removeEventListener("keydown", onKeyDown, true);
        escHandlerBound=false;
    };
    const removeLightbox=()=>{
        const existing=document.getElementById(LIGHTBOX_ID);
        if(existing) existing.remove();
        unbindEsc();
    };
    const showImagePreview=(src)=>{
        if(!src || typeof src!=="string") return;
        removeLightbox();
        const host=document.querySelector('.pause-layout') || document.querySelector('.redline-pause') || document.body;
        const overlay=document.createElement("div");
        overlay.id=LIGHTBOX_ID;
        overlay.className="rl-pm-image-lightbox";
        overlay.innerHTML=`<div class="rl-pm-image-lightbox-backdrop"></div><div class="rl-pm-image-lightbox-dialog" role="dialog" aria-modal="true" aria-label="Image preview"><button type="button" class="rl-pm-image-lightbox-close" aria-label="Close"><i class="fas fa-times"></i></button><div class="rl-pm-image-lightbox-stage"><img class="rl-pm-image-lightbox-img" src="${src}" alt=""></div><div class="rl-pm-image-lightbox-hint">Scroll to zoom • Drag to move • Double click to reset</div></div>`;
        host.appendChild(overlay);

        const dialog=overlay.querySelector('.rl-pm-image-lightbox-dialog');
        const stage=overlay.querySelector('.rl-pm-image-lightbox-stage');
        const img=overlay.querySelector('.rl-pm-image-lightbox-img');
        let scale=1, x=0, y=0, dragging=false, startX=0, startY=0;
        const minScale=1, maxScale=5;
        const update=()=>{
            img.style.transform=`translate(${x}px, ${y}px) scale(${scale})`;
            stage.classList.toggle('is-zoomed', scale>1.001);
            stage.classList.toggle('is-dragging', dragging);
        };
        const reset=()=>{ scale=1; x=0; y=0; dragging=false; update(); };
        const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));

        overlay.addEventListener("click", (ev)=>{
            if(ev.target===overlay || ev.target.classList.contains("rl-pm-image-lightbox-backdrop") || ev.target.closest(".rl-pm-image-lightbox-close")){
                ev.preventDefault();
                ev.stopPropagation();
                if(typeof ev.stopImmediatePropagation==="function") ev.stopImmediatePropagation();
                removeLightbox();
            }
        }, true);

        stage.addEventListener('wheel',(ev)=>{
            ev.preventDefault();
            ev.stopPropagation();
            const next=clamp(scale + (ev.deltaY<0 ? 0.2 : -0.2), minScale, maxScale);
            if(next===minScale && scale!==minScale){
                scale=next; x=0; y=0; update(); return;
            }
            scale=next;
            update();
        }, {passive:false});

        stage.addEventListener('mousedown',(ev)=>{
            if(scale<=1.001) return;
            dragging=true;
            startX=ev.clientX-x;
            startY=ev.clientY-y;
            update();
            ev.preventDefault();
        });
        window.addEventListener('mousemove',(ev)=>{
            const existing=document.getElementById(LIGHTBOX_ID);
            if(!existing || !dragging) return;
            x=ev.clientX-startX;
            y=ev.clientY-startY;
            update();
        });
        window.addEventListener('mouseup',()=>{
            if(!dragging) return;
            dragging=false;
            update();
        });
        stage.addEventListener('mouseleave',()=>{
            if(!dragging) return;
            dragging=false;
            update();
        });
        stage.addEventListener('dblclick',(ev)=>{
            ev.preventDefault();
            if(scale>1.001){ reset(); }
            else { scale=2; update(); }
        });
        img.addEventListener('dragstart',(ev)=>ev.preventDefault());
        dialog.addEventListener('click',(ev)=>ev.stopPropagation());
        update();
        bindEsc();
    };
    document.addEventListener("click",(ev)=>{
        const trigger=ev.target && ev.target.closest ? ev.target.closest(".popout-image-link, .popout-list-image, .popout-image") : null;
        if(!trigger) return;
        if(trigger.closest && trigger.closest(".paddock-club-popout-window")) return;
        const src=(trigger.getAttribute("data-src") || trigger.getAttribute("href") || trigger.getAttribute("src") || trigger.querySelector?.("img")?.getAttribute("src") || "").trim();
        if(!src || src==="#" || src.toLowerCase().startsWith("javascript:")) return;
        ev.preventDefault();
        ev.stopPropagation();
        if(typeof ev.stopImmediatePropagation==="function") ev.stopImmediatePropagation();
        showImagePreview(src);
    },true);
}catch(e){console.warn("[rl_pausemenu] image preview patch failed",e)}})();

;(()=>{try{
    document.addEventListener("click",(ev)=>{
        const box=document.getElementById("rl-pm-image-lightbox");
        if(!box) return;
        const dialog=box.querySelector(".rl-pm-image-lightbox-dialog");
        if(!dialog) return;
        const rect=dialog.getBoundingClientRect();
        const hitX=ev.clientX >= rect.right-72 && ev.clientX <= rect.right+12;
        const hitY=ev.clientY >= rect.top-12 && ev.clientY <= rect.top+72;
        if(hitX && hitY){
            ev.preventDefault();
            ev.stopPropagation();
            if(typeof ev.stopImmediatePropagation==="function") ev.stopImmediatePropagation();
            box.remove();
        }
    },true);
}catch(e){console.warn("[rl_pausemenu] close hitbox patch failed",e)}})();


;(()=>{try{
    const ensureJobLine=(player={})=>{
        const profile=document.querySelector(".feed-profile");
        const nameEl=profile ? profile.querySelector(".feed-name") : null;
        if(!profile || !nameEl) return;

        let line=profile.querySelector(".feed-jobline");
        if(!line){
            line=document.createElement("div");
            line.className="feed-jobline";
            line.innerHTML='<span class="feed-job"></span><span class="feed-grade"></span>';
            nameEl.insertAdjacentElement("afterend", line);
        }

        const job=(player.job || "").toString().trim();
        const grade=(player.grade || "").toString().trim();

        const jobEl=line.querySelector(".feed-job");
        const sepEl=line.querySelector(".feed-job-sep");
        const gradeEl=line.querySelector(".feed-grade");

        if(jobEl) jobEl.textContent=job;
        if(gradeEl) gradeEl.textContent=grade;

        const hasJob=job.length > 0;
        const hasGrade=grade.length > 0;

        if(jobEl) jobEl.style.display=hasJob ? "" : "none";
        if(gradeEl) gradeEl.style.display=hasGrade ? "" : "none";
        if(sepEl) sepEl.style.display=(hasJob && hasGrade) ? "" : "none";
        line.style.display=(hasJob || hasGrade) ? "flex" : "none";
    };

    window.addEventListener("message",(event)=>{
        const msg=event.data || {};
        if(msg.action==="updatePlayerData" && msg.data){
            window.__rlPausePlayerData=Object.assign({}, window.__rlPausePlayerData || {}, msg.data);
            requestAnimationFrame(()=>ensureJobLine(window.__rlPausePlayerData || {}));
            setTimeout(()=>ensureJobLine(window.__rlPausePlayerData || {}), 80);
        }

        if(msg.action==="setVisible" && msg.data===true){
            setTimeout(()=>ensureJobLine(window.__rlPausePlayerData || {}), 120);
            setTimeout(()=>ensureJobLine(window.__rlPausePlayerData || {}), 280);
        }
    });

    const observer=new MutationObserver(()=>ensureJobLine(window.__rlPausePlayerData || {}));
    observer.observe(document.body,{childList:true,subtree:true});

    setTimeout(()=>ensureJobLine(window.__rlPausePlayerData || {}), 250);
}catch(e){console.warn("[rl_pausemenu] job/grade patch failed", e)}})();


;(()=>{try{
    const post=(name,data={})=>{
        if(typeof GetParentResourceName!=="function") return;
        fetch(`https://${GetParentResourceName()}/${name}`,{
            method:"POST",
            headers:{"Content-Type":"application/json"},
            body:JSON.stringify(data)
        }).catch(()=>{});
    };

    document.addEventListener("click",(ev)=>{
        const target=ev.target;
        if(!target || !target.closest) return;
        if(target.closest(".open-gps-btn")) return;

        const mapCard=target.closest(".map-card, .gta-leaflet-host, .leaflet-container");
        if(!mapCard) return;

        ev.preventDefault();
        ev.stopPropagation();
        if(typeof ev.stopImmediatePropagation==="function") ev.stopImmediatePropagation();

        post("map",{});
    },true);
}catch(e){console.warn("[rl_pausemenu] map click patch failed",e)}})();


;(()=>{try{
    const POPUP_ID='rl-pm-paddock-popup';
    const IMG_SRC='https://raw.githubusercontent.com/shotarodev88/shotaro_cdn/917463f3c2213d82f991b0dcedffa1503c0d99b3/uploads/PADDOCK_TEMPLATE_2.png';
    let escBound=false;

    const removePopup=()=>{
        const existing=document.getElementById(POPUP_ID);
        if(existing) existing.remove();
        if(escBound){
            document.removeEventListener('keydown', onKeyDown, true);
            escBound=false;
        }
    };

    const onKeyDown=(ev)=>{
        if(ev.key!=='Escape') return;
        const existing=document.getElementById(POPUP_ID);
        if(!existing) return;
        ev.preventDefault();
        ev.stopPropagation();
        if(typeof ev.stopImmediatePropagation==='function') ev.stopImmediatePropagation();
        removePopup();
    };

    const showPopup=()=>{
        removePopup();
        const host=document.body;
        if(!host) return;

        const overlay=document.createElement('div');
        overlay.id=POPUP_ID;
        overlay.className='popout-overlay paddock-club-popout-overlay';
        overlay.innerHTML=`<div class="popout-window paddock-club-popout-window" role="dialog" aria-modal="true" aria-label="Paddock Club Perks"><button type="button" class="popout-close paddock-club-popout-close" aria-label="Close"><i class="fas fa-times"></i></button><p class="popout-meta">Paddock pass comparison & perks</p><h2 class="popout-title">Join the Paddock Club</h2><div class="paddock-club-image-trigger"><img class="popout-image paddock-club-popout-image" src="${IMG_SRC}" alt="Paddock Club perks"></div></div>`;
        host.appendChild(overlay);

        overlay.addEventListener('click',(ev)=>{
            if(ev.target===overlay) removePopup();
        });
        const win=overlay.querySelector('.paddock-club-popout-window');
        if(win) win.addEventListener('click',(ev)=>ev.stopPropagation());
        const closeBtn=overlay.querySelector('.paddock-club-popout-close');
        if(closeBtn) closeBtn.addEventListener('click', removePopup);

        document.addEventListener('keydown', onKeyDown, true);
        escBound=true;
    };

    document.addEventListener('click',(ev)=>{
        const target=ev.target;
        if(!target || !target.closest) return;
        const btn=target.closest('.paddock-club-btn');
        if(!btn) return;
        ev.preventDefault();
        ev.stopPropagation();
        if(typeof ev.stopImmediatePropagation==='function') ev.stopImmediatePropagation();
        showPopup();
    }, true);
}catch(e){console.warn('[rl_pausemenu] paddock popup patch failed', e)}})();
